('PT158-S2-Q1','note','32ce5ca9-d0d8-4956-b69e-625374adc0d9','B','d8f86a89-9307-4a91-b533-ae10c0fc5553','e435d5458131a2641f12c0849d34c83b','c8369e62c9afb6418e92b4d735c4b081',NULL,NULL),
('PT158-S2-Q1','note','32ce5ca9-d0d8-4956-b69e-625374adc0d9','C','20d77399-3d52-4fb3-a581-36048f2ce04e','cd725521a81a7ad8c9dab15a7c3ad7aa','1edec078d11fd2dc5a008a616e1b91d7',NULL,NULL),
('PT158-S2-Q1','note','32ce5ca9-d0d8-4956-b69e-625374adc0d9','D','76b5fd66-7fcf-4f84-beff-8805c19eea8d','159a9fa914757ef185322baa11269e3e','5b156af67aefcc3cdd1722e6056f87b3',NULL,NULL),
('PT158-S2-Q1','note','32ce5ca9-d0d8-4956-b69e-625374adc0d9','E','11e05fdf-74f6-4679-9730-914509d5450f','15ba118efee26d97ba4b3b6dd4c27904','0ab71b839ed6fdefad665fbf053744cf',NULL,NULL)), actual as (
 select 'step'::text kind, explanation_id::text eid, position::text slot,id::text rid,md5(body) body_md5,coalesce(label,'') label from lr_explanation_steps
 union all select 'note',explanation_id::text,letter::text,id::text,md5(body),null::text from lr_explanation_choice_notes
), checked as (
 select e.*,count(a.rid)::integer matches,
 count(a.rid) filter(where a.body_md5=e.new_md5 and (e.rid is null or a.rid=e.rid) and (e.kind='note' or a.label=e.new_label))::integer final_matches,
 count(a.rid) filter(where a.body_md5=e.old_md5 and (e.rid is null or a.rid=e.rid) and (e.kind='note' or a.label=e.old_label))::integer old_matches,
 jsonb_agg(jsonb_build_object('rid',a.rid,'md5',a.body_md5,'label',a.label)) filter(where a.rid is not null) actual
 from expected e left join actual a on a.kind=e.kind and a.eid=e.eid and a.slot=e.slot
 group by e.qid,e.kind,e.eid,e.slot,e.rid,e.new_md5,e.old_md5,e.new_label,e.old_label
), extras as (
 select a.kind,a.eid,a.slot,count(*) count from actual a
 where a.eid in (select distinct eid from expected) and not exists(select 1 from expected e where e.eid=a.eid and e.kind=a.kind and e.slot=a.slot)
 group by a.kind,a.eid,a.slot
)
select jsonb_build_object('batch','e05','expected_rows',(select count(*) from checked),'final_rows',(select count(*) from checked where matches=1 and final_matches=1),'old_rows',(select count(*) from checked where matches=1 and old_matches=1),'missing',(select count(*) from checked where matches=0),'duplicate_slots',(select count(*) from checked where matches>1),'mismatches',coalesce((select jsonb_agg(jsonb_build_object('qid',qid,'kind',kind,'slot',slot,'expected_id',rid,'expected_md5',new_md5,'matches',matches,'old_matches',old_matches,'actual',actual)) from checked where matches<>1 or final_matches<>1),'[]'::jsonb),'extra_slots',coalesce((select jsonb_agg(to_jsonb(extras)) from extras),'[]'::jsonb)) audit;
